// Obtém as mensagens do usuário e bot
const userMessages = $('SET TEXT').first().json.LIST_ARRAY;
const botMessagesRaw = $('Set MSG').first().json.output;

// Obtém dados do banco de dados (INPUT - Ajustado para nó inicial)
const dbData = $('Get User').first().json;
const dateRegisterRaw = dbData.dateRegister;
const lastInteractionRaw = dbData.lastInteraction;

// Converte valores para números (garantindo que não seja NaN)
const pontosAtuais = parseInt(dbData.interactionPoints) || 0;
const interacoesAnteriores = parseInt(dbData.totalInteracoesUser) || 0;
const diasComInteracaoAnteriores = parseInt(dbData.diasComInteracao) || 0;
const interacoesDiarias = parseInt(dbData.interacoesDiarias) || 0;
const interacoesSemanais = parseInt(dbData.interacoesSemanais) || 0;
const interacoesMensais = parseInt(dbData.interacoesMensais) || 0;
const sequenciaDiasAtual = parseInt(dbData.sequenciaDias) || 0;
const ultimaDataSequenciaRaw = dbData.ultimaDataSequencia || dateRegisterRaw;

// Processa mensagens
const userMsgArray = typeof userMessages === 'string' 
  ? userMessages.split('\\n').filter(msg => msg.trim() !== '')
  : Array.isArray(userMessages) ? userMessages : [];

// CONSTANTES
const INTERVALO_MINIMO = 5; // minutos
const PESO_MSG_DIARIA = 2;
const PESO_MSG_SEMANAL = 1;
const PESO_STREAK = 10;
const PESO_TOTAL = 0.1;

// --- FUNÇÕES AUXILIARES ---
// Ajuste de Fuso Horário Brasil (UTC-3)
function getBrazilDate() {
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000); 
  return new Date(utc - (3 * 3600000));
}

// Helper seguro para parsear datas
function parseDate(dateStr) {
  if (!dateStr) return null;
  if (dateStr instanceof Date) return new Date(dateStr.getTime());

  const s = String(dateStr).trim();

  // 1. Tenta parsear formato novo DD/MM/YYYY (com barras)
  const brRegex = /^(\d{2})\/(\d{2})\/(\d{4})(?:\s(\d{2}):(\d{2}):(\d{2}))?/;
  const brMatch = s.match(brRegex);
  if (brMatch) {
    return new Date(
      parseInt(brMatch[3]), 
      parseInt(brMatch[2]) - 1, 
      parseInt(brMatch[1]), 
      brMatch[4] ? parseInt(brMatch[4]) : 0, 
      brMatch[5] ? parseInt(brMatch[5]) : 0, 
      brMatch[6] ? parseInt(brMatch[6]) : 0
    );
  }

  // 2. Fallback para parse padrão (ISO, MM-DD-YYYY legacy)
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function formatDateForDB(dateObj) {
  const d = (dateObj instanceof Date) ? dateObj : parseDate(dateObj);
  if (!d || isNaN(d.getTime())) return String(dateObj); // Fallback se falhar
  const pad = (n) => String(n).padStart(2, '0');
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function isMesmoDia(d1, d2) {
  const a = parseDate(d1);
  const b = parseDate(d2);
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

function isMesmaSemana(d1, d2) {
  const a = parseDate(d1);
  const b = parseDate(d2);
  if (!a || !b) return false;
  const startA = new Date(a); startA.setDate(a.getDate() - a.getDay()); startA.setHours(0,0,0,0);
  const startB = new Date(b); startB.setDate(b.getDate() - b.getDay()); startB.setHours(0,0,0,0);
  return startA.getTime() === startB.getTime();
}

function isMesmoMes(d1, d2) {
  const a = parseDate(d1); 
  const b = parseDate(d2);
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

function isDiaConsecutivo(anterior, atual) {
  const a = parseDate(anterior);
  const b = parseDate(atual);
  if (!a || !b) return false;
  a.setHours(0,0,0,0);
  b.setHours(0,0,0,0);
  const diffDays = Math.floor((b - a) / (1000 * 60 * 60 * 24));
  return diffDays === 1;
}

