const dataAtual = getBrazilDate();
const novaLastInteraction = formatDateForDB(dataAtual); 

// Checagem de Períodos
const mesmoDia = isMesmoDia(lastInteractionRaw, dataAtual);
const mesmaSemana = isMesmaSemana(lastInteractionRaw, dataAtual);
const mesmoMes = isMesmoMes(lastInteractionRaw, dataAtual);
const diaConsecutivo = isDiaConsecutivo(ultimaDataSequenciaRaw, dataAtual);

// 1. Lógica de Sequência (Streak)
