if (mesmoDia) {
  novaSequenciaDias = sequenciaDiasAtual;
} else if (diaConsecutivo) {
  novaSequenciaDias = sequenciaDiasAtual + 1;
} else {
  novaSequenciaDias = 0;
}

const novaUltimaDataSequencia = formatDateForDB(dataAtual);

// 2. Atualiza Contadores
const msgHoje = userMsgArray.length;
const novasInteracoesDiarias = mesmoDia ? interacoesDiarias + msgHoje : msgHoje;
const novasInteracoesSemanais = mesmaSemana ? interacoesSemanais + msgHoje : msgHoje;
const novasInteracoesMensais = mesmoMes ? interacoesMensais + msgHoje : msgHoje;

const novoTotalInteracoes = interacoesAnteriores + msgHoje;
const novosDiasComInteracao = mesmoDia ? diasComInteracaoAnteriores : diasComInteracaoAnteriores + 1;

// 3. Média de Interações
const novaMediaInteracoesPorDia = novosDiasComInteracao > 0 
  ? (novoTotalInteracoes / novosDiasComInteracao).toFixed(2) 
  : 0;

// 4. Lead Scoring
let leadScore = (novasInteracoesDiarias * PESO_MSG_DIARIA) + 
                (novasInteracoesSemanais * PESO_MSG_SEMANAL) + 
                (novaSequenciaDias * PESO_STREAK) + 
                (novoTotalInteracoes * PESO_TOTAL);

let categoria = "Bronze";
if (leadScore >= 500) categoria = "Diamante";
else if (leadScore >= 200) categoria = "Ouro";
else if (leadScore >= 100) categoria = "Prata";

// 5. Dias desde registro
