if (dateRegisterRaw) {
  const dReg = parseDate(dateRegisterRaw);
  if (dReg) {
     diasDesdeRegistro = Math.floor((dataAtual - dReg) / (1000 * 60 * 60 * 24));
  }
}

// Pontos (Legado)
let novoTotalPontos = pontosAtuais;
const dLast = parseDate(lastInteractionRaw);
if (!dLast || (dataAtual - dLast) / 60000 >= INTERVALO_MINIMO) {
    novoTotalPontos += 1;
}

