  platform: { call_count: 0, total_time: 0, total_cputime: 0, _meta_emitted: false },
  business: [],
  isLimited: false,
  errorCode: null,
  errorMessage: "",
  estimatedCallsConsumed: 0,
  nodesTracked: [],
  anyMetaExecuted: false
};

metaNodes.forEach(nodeName => {
  try {
    // Checking if node was executed and has output data
    const nodeOutput = $(nodeName).all(); 
    if (nodeOutput && nodeOutput.length > 0) {
      usage.anyMetaExecuted = true;
      const firstItem = nodeOutput[0].json;

      // We track which nodes were hit
      usage.nodesTracked.push(`${nodeName} (${nodeOutput.length} item(s))`);

      const headers = firstItem.headers || {};
      const body = firstItem.body || {};
      const statusCode = firstItem.statusCode || 200;

      // 1. Headers (Capture the most recent platform metrics)
      if (headers['x-app-usage']) {
        try {
          const platformData = JSON.parse(headers['x-app-usage']);
          usage.platform.call_count = Math.max(usage.platform.call_count, platformData.call_count);
          usage.platform.total_time = Math.max(usage.platform.total_time, platformData.total_time);
          usage.platform.total_cputime = Math.max(usage.platform.total_cputime, platformData.total_cputime);
          usage.platform._meta_emitted = true;
        } catch (e) {}
      }

      // 2. Error Detection from any node
      const rateLimitErrorCodes = [4, 17, 32, 613, 80000, 80001, 80002, 80003, 80004, 80005, 80006, 80008, 80009, 80014];
      if (body.error) {
        usage.errorCode = body.error.code;
        usage.errorMessage = body.error.message;
        if (rateLimitErrorCodes.includes(usage.errorCode)) usage.isLimited = true;
      } else if (statusCode === 429) {
        usage.isLimited = true;
        usage.errorMessage = "General Rate Limit Reached (429)";
      }
    }
